import { createClient, type SupabaseClient } from "@supabase/supabase-js";

export type RoomVote = "pass" | "interested" | "love";

export type RoomRestaurant = {
  id: string;
  name: string;
  cuisine: string;
  rating: number;
  reviewCount: number;
  priceLevel: number;
  address: string;
