const r=await Promise.allSettled([
 tools.exec_command({cmd:"rg -n 'trail_monitor|value_type|result_type|trigger_types|code_review_comments' cmd/entire/cli/runner*.go cmd/entire/cli/runnerdefaults | head -120","workdir":"/tmp/entire-cli-runner-reference","max_output_tokens":5000}),
 tools.exec_command({cmd:"sed -n '1,220p' cmd/entire/cli/runner_apply.go && sed -n '1,170p' cmd/entire/cli/runner_init.go","workdir":"/tmp/entire-cli-runner-reference","max_output_tokens":7000}),
 tools.exec_command({cmd:"sed -n '1,120p' cmd/entire/cli/runnerdefaults/runners/trail-confidence.json && sed -n '1,120p' cmd/entire/cli/runnerdefaults/runners/trail-drift.json && sed -n '1,120p' cmd/entire/cli/runnerdefaults/runners/trail-security.json","workdir":"/tmp/entire-cli-runner-reference","max_output_tokens":7500}),
 tools.exec_command({cmd:"git status --short","workdir":"/Users/rizelscarlett/Documents/work/girl-dinner","max_output_tokens":1000})
]);for(let i=0;i<r.length;i++)text(JSON.stringify({i,result:r[i]}));

